-- SUPERVISION 360 - Importacion inicial (29 escuelas del relevamiento junio 2026)
-- Ejecutar en SQL Editor de un proyecto Supabase administrado y autorizado.
-- RLS queda activado SIN politicas de acceso de cliente: inicialmente solo el administrador
-- via SQL Editor puede leer o cambiar estos registros. No abrir permisos anon/public.
BEGIN;
CREATE TABLE IF NOT EXISTS public.escuelas (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  numero_escuela text NOT NULL UNIQUE,
  nombre text NOT NULL,
  localidad text,
  departamento text,
  direccion text,
  telefono text,
  email text,
  director_nombre text,
  latitud numeric(10,7),
  longitud numeric(10,7),
  categoria text,
  modalidad text,
  datos_extra jsonb NOT NULL DEFAULT '{}'::jsonb,
  creado_en timestamptz NOT NULL DEFAULT now(),
  actualizado_en timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.escuelas ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.escuelas FROM anon, authenticated;

CREATE TABLE IF NOT EXISTS public.relevamientos_escuela (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 escuela_id uuid NOT NULL REFERENCES public.escuelas(id) ON DELETE CASCADE,
 fecha_relevamiento text NOT NULL,
 fuente text NOT NULL,
 matricula_primario integer,
 matricula_inicial integer,
 equipo_directivo_cantidad integer,
 cargos_maestros_grado integer,
 cargos_excedentes text,
 necesidades_cargos text,
 fila_origen integer,
 estado text,
 datos_originales jsonb NOT NULL DEFAULT '{}'::jsonb,
 creado_en timestamptz NOT NULL DEFAULT now(),
 CONSTRAINT relevamiento_escuela_fuente_unico UNIQUE(escuela_id, fecha_relevamiento, fuente)
);
ALTER TABLE public.relevamientos_escuela ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.relevamientos_escuela FROM anon, authenticated;

CREATE OR REPLACE FUNCTION public.supervision360_tocar_actualizado()
RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN NEW.actualizado_en = now(); RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS trig_supervision360_escuelas_actualizado ON public.escuelas;
CREATE TRIGGER trig_supervision360_escuelas_actualizado BEFORE UPDATE ON public.escuelas
FOR EACH ROW EXECUTE FUNCTION public.supervision360_tocar_actualizado();

-- Datos agrupados del archivo revisado. No se importan nombres de alumnos,
-- diagnósticos ni información socioeducativa sensible.
CREATE TEMP TABLE tmp_import_escuelas (fila jsonb) ON COMMIT DROP;
