INSERT INTO public.escuelas(numero_escuela,nombre,localidad,departamento,categoria,modalidad,datos_extra)
SELECT fila->>'numero_escuela', fila->>'nombre', fila->>'localidad', fila->>'departamento',
       fila->>'categoria', fila->>'modalidad',
       jsonb_build_object('relevamiento_inicial','Relevamiento junio 2026')
FROM tmp_import_escuelas
ON CONFLICT(numero_escuela) DO NOTHING; -- no sobreescribir ediciones de Silvia

INSERT INTO public.relevamientos_escuela(
  escuela_id,fecha_relevamiento,fuente,matricula_primario,matricula_inicial,
  equipo_directivo_cantidad,cargos_maestros_grado,cargos_excedentes,
  necesidades_cargos,fila_origen,estado,datos_originales)
SELECT e.id,
       t.fila->>'fecha_relevamiento',t.fila->>'fuente',
       NULLIF(t.fila->>'matricula_primario','')::integer,
       NULLIF(t.fila->>'matricula_inicial','')::integer,
       NULLIF(t.fila->>'equipo_directivo_cantidad','')::integer,
       NULLIF(t.fila->>'cargos_maestros_grado','')::integer,
       t.fila->>'cargos_excedentes', t.fila->>'necesidades_cargos',
       NULLIF(t.fila->>'fila_origen','')::integer,
       t.fila->>'estado',t.fila
FROM tmp_import_escuelas t
JOIN public.escuelas e ON e.numero_escuela=t.fila->>'numero_escuela'
ON CONFLICT (escuela_id,fecha_relevamiento,fuente) DO NOTHING;
COMMIT;

-- Consultas de verificacion (ejecutar despues):
SELECT COUNT(*) AS escuelas_cargadas FROM public.escuelas;
SELECT COUNT(*) AS relevamientos_cargados FROM public.relevamientos_escuela;
SELECT numero_escuela,nombre,localidad FROM public.escuelas ORDER BY numero_escuela;
-- Validar anomalía original: escuela 424, cargos_maestros_grado=442.
-- Escuela 433: este relevamiento de junio NO reemplaza el informe SIGAE de octubre.
